/// The credential in the form the authenticator port takes.
fn for_port(credential: PresentedCredential) -> davhaven_ports::PresentedCredential {
    match credential {
        PresentedCredential::Basic { username, password } => {
            davhaven_ports::PresentedCredential::Basic { username, password }
        }
        PresentedCredential::Bearer(secret) => davhaven_ports::PresentedCredential::Bearer(secret),
        PresentedCredential::Feed(secret) => davhaven_ports::PresentedCredential::Feed(secret),
        PresentedCredential::Rsvp(secret) => davhaven_ports::PresentedCredential::Rsvp(secret),
    }
}

/// A keyed, hex-encoded digest of `label` for rate limiter keys.
fn keyed(core: &AppCore, label: &str) -> String {
    let mac = core
        .deps()
        .keyring
        .sign(
            KeyPurpose::CacheKey,
            format!("davhaven/auth-failure/v1/{label}").as_bytes(),
        )
        .mac;
    let mut hex = String::with_capacity(32);
    for byte in mac.iter().take(16) {
        // Writing into a `String` cannot fail.
        let _ = write!(hex, "{byte:02x}");
    }
    hex
}

/// The failure buckets of a request: one per (login, client address) and one per client address.
fn failure_keys(
    core: &AppCore,
    channel: Channel,
    credential: &davhaven_ports::PresentedCredential,
    ip: Option<IpAddr>,
) -> Vec<RateKey> {
    let login = match credential {
        davhaven_ports::PresentedCredential::Basic { username, .. } => username.trim().to_ascii_lowercase(),
        davhaven_ports::PresentedCredential::Bearer(secret)
        | davhaven_ports::PresentedCredential::Feed(secret)
        | davhaven_ports::PresentedCredential::Rsvp(secret) => secret.expose_secret().chars().take(20).collect(),
    };
    // An IPv6 client is its /64: a fresh address of the same network is no fresh failure budget.
    let address = ip.map_or_else(|| "-".to_owned(), |ip| bucket_address(ip).to_string());
    let mut keys = vec![RateKey::auth_login_ip(keyed(
        core,
        &format!("login/{channel}/{login}/{address}"),
    ))];
    if ip.is_some() {
        keys.push(RateKey::auth_ip(keyed(core, &format!("ip/{channel}/{address}"))));
    }
    keys
}

impl AuthServiceImpl {
    /// Whether any failure bucket of the request is exhausted: the wait to report, if so.
    async fn blocked(&self, keys: &[RateKey]) -> Option<Duration> {
        let mut wait: Option<Duration> = None;
        for key in keys {
            // A limiter that cannot answer must not lock everybody out.
            if let Ok(decision) = self.core.deps().rate_limiter.check(key, 0).await
                && !decision.allowed
            {
                let needed = decision.retry_after.unwrap_or(DEFAULT_RETRY_AFTER);
                wait = Some(wait.map_or(needed, |current| current.max(needed)));
            }
        }
        wait
    }

    /// Records a refusal: the metric and one unit of every failure bucket.
    async fn failed(&self, mechanism: CredentialKind, reason: &'static str, keys: &[RateKey]) {
        metrics::counter!(
            "davhaven_auth_failures_total",
            "mechanism" => mechanism.as_str(),
            "reason" => reason
        )
        .increment(1);
        for key in keys {
            let _ = self.core.deps().rate_limiter.check(key, 1).await;
        }
    }

    /// Builds the context of an accepted credential and checks it against the tenant the request names.
    ///
    /// A credential is refused when it does not fit the channel or the mechanism it was presented on (an
    /// authenticator that accepts an app password on the API would otherwise be trusted), when its tenant is not
    /// the one of the path, or when the tenant is not active. System tokens belong to no tenant and name one only
    /// through the hint.
    async fn context(
        &self,
        auth: davhaven_ports::Authenticated,
        request: &RequestMeta,
        mechanism: CredentialKind,
    ) -> Result<RequestContext, Refusal> {
        let deps = self.core.deps();
        if auth.credential.kind != mechanism || !credential_fits(mechanism, request.channel) {
            return Err(Refusal::new("wrong_surface"));
        }
        let tenant = match (&auth.actor, auth.tenant) {
            (Actor::SystemToken(_), _) => match &request.tenant_hint {
                Some(slug) => {
                    let mut tx = deps.database.begin_system().await?;
                    let named = tx.tenants().find_by_slug(slug).await?;
                    tx.commit().await?;
                    named.map_or_else(|| davhaven_domain::TenantId::from_uuid(Uuid::nil()), |tenant| tenant.id)
                }
                None => davhaven_domain::TenantId::from_uuid(Uuid::nil()),
            },
            (_, Some(tenant)) => {
                let Some(known) = self.core.tenants().lookup(&self.core, tenant).await? else {
                    return Err(Refusal::new("tenant_mismatch"));
                };
                if known.status != TenantStatus::Active {
                    return Err(Refusal::new("suspended"));
                }
                // A valid credential presented for the path of another tenant is authenticated; what is in the other
                // tenant is invisible to it (ADR-0012): not found, and not a failed authentication.
                if request.tenant_hint.as_ref().is_some_and(|hint| hint != &known.slug) {
                    return Err(Refusal::Hidden);
                }
                // MCP is opt-in per tenant (`tenant.settings.mcp_enabled`, off by default): for a tenant that has not
                // switched it on, the endpoint does not exist, whatever tokens its principals hold.
                if request.channel == Channel::Mcp && !known.mcp_enabled {
                    return Err(Refusal::Hidden);
                }
                tenant
            }
            (_, None) => return Err(Refusal::new("tenant_mismatch")),
        };
        Ok(RequestContext {
            tenant,
            actor: auth.actor,
            scopes: auth.scopes,
            channel: request.channel,
            credential: Some(auth.credential),
            request_id: request.request_id,
            locale: None,
            client_ip: request.client_ip,
        })
    }
}

/// Whether a credential of `kind` is accepted on `channel`: app passwords on DAV, API tokens on the API and MCP,
/// feed tokens on feeds, RSVP tokens on RSVP pages (PLAN 2.6, `ENGINEERING_RULES` R6).
const fn credential_fits(kind: CredentialKind, channel: Channel) -> bool {
    matches!(
        (kind, channel),
        (CredentialKind::AppPassword, Channel::Dav)
            | (CredentialKind::ApiToken, Channel::Api | Channel::Mcp)
            | (CredentialKind::FeedToken, Channel::Feed)
            | (CredentialKind::RsvpToken, Channel::Rsvp)
    )
}

/// Why an accepted credential was refused after all: the `reason` label of the failure counter. The client sees the
/// same `Unauthenticated` for every one of them; an infrastructure failure is a different thing (`Failure`).
enum Refusal {
    Refused(&'static str),
    /// A valid credential for the path of another tenant: not found, not a failure.
    Hidden,
    Failure(AppError),
}

impl Refusal {
    const fn new(reason: &'static str) -> Self {
        Self::Refused(reason)
    }
}

impl From<AppError> for Refusal {
    fn from(error: AppError) -> Self {
        Self::Failure(error)
    }
}

impl From<StoreError> for Refusal {
    fn from(error: StoreError) -> Self {
        Self::Failure(error.into())
    }
}

/// What of an [`AuthRequest`] is still needed after its credential was taken out.
struct RequestMeta {
    channel: Channel,
    tenant_hint: Option<davhaven_domain::TenantSlug>,
    client_ip: Option<IpAddr>,
    request_id: davhaven_domain::RequestId,
}

impl AuthServiceImpl {
    /// Records the refusal of a budget: the audit records that [`TripLog`] says are due. Best effort: the call is refused
    /// whether or not the record can be written.
    async fn record_trip(&self, ctx: &RequestContext, token: TokenId, class: BudgetClass) {
        let due = self.trips.note(token, class, self.core.deps().clock.now()).await;
        let counts: Vec<u32> = due.closed.into_iter().chain(due.opened.then_some(1)).collect();
        if counts.is_empty() {
            return;
        }
        let journal = Journal::new(&self.core, ctx);
        let written: AppResult<()> = async {
            let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            for count in counts {
                journal
                    .audit(
                        tx.as_mut(),
                        AuditEvent::RateLimitTripped(RateLimitAudit {
                            bucket: class.name().to_owned(),
                            count,
                        }),
                    )
                    .await?;
            }
            tx.commit().await?;
            Ok::<(), AppError>(())
        }
        .await;
        if let Err(error) = written {
            tracing::warn!(kind = ?error.kind(), "the audit record of a refused budget could not be written");
        }
    }
}

#[async_trait]
impl AuthService for AuthServiceImpl {
    async fn charge_budget(&self, ctx: &RequestContext, class: BudgetClass) -> AppResult<()> {
        let Some(token) = ctx.actor.token() else {
            return Ok(());
        };
        let bucket = match class {
            BudgetClass::McpRead => RateKey::MCP_READ,
            BudgetClass::McpWrite => RateKey::MCP_WRITE,
        };
        let key = RateKey::new(bucket, keyed(&self.core, &format!("budget/{}/{token}", class.name())));
        match self.core.deps().rate_limiter.check(&key, 1).await {
            Ok(decision) if decision.allowed => Ok(()),
            Ok(decision) => {
                metrics::counter!("davhaven_budget_refusals_total", "class" => class.name()).increment(1);
                self.record_trip(ctx, token, class).await;
                Err(AppError::rate_limited(
                    decision.retry_after.unwrap_or(DEFAULT_RETRY_AFTER),
                ))
            }
            Err(error) => {
                // A limiter that cannot answer must not stop the calendar tools.
                tracing::warn!(kind = error.kind.as_str(), "the limiter of the budgets did not answer");
                Ok(())
            }
        }
    }

    async fn authenticate(&self, request: AuthRequest) -> AppResult<RequestContext> {
        let AuthRequest {
            channel,
            tenant_hint,
            credential,
            client_ip,
            request_id,
        } = request;
        let mechanism = credential.kind();
        let presented = for_port(credential);
        let keys = failure_keys(&self.core, channel, &presented, client_ip);
        if let Some(wait) = self.blocked(&keys).await {
            metrics::counter!(
                "davhaven_auth_failures_total",
                "mechanism" => mechanism.as_str(),
                "reason" => "backoff"
            )
            .increment(1);
            return Err(AppError::rate_limited(wait));
        }
        let hint = AuthHint {
            channel,
            tenant_hint: tenant_hint.clone(),
            client_ip,
            request_id,
        };
        let mut outcome = AuthOutcome::NotApplicable;
        for authenticator in &self.core.deps().authenticators {
            match authenticator.authenticate(&presented, &hint).await? {
                AuthOutcome::NotApplicable => {}
                decided => {
                    outcome = decided;
                    break;
                }
            }
        }
        match outcome {
            AuthOutcome::Accepted(auth) => {
                let rest = RequestMeta {
                    channel,
                    tenant_hint,
                    client_ip,
                    request_id,
                };
                match self.context(auth, &rest, mechanism).await {
                    Ok(context) => Ok(context),
                    Err(Refusal::Refused(reason)) => {
                        metrics::counter!(
                            "davhaven_auth_failures_total",
                            "mechanism" => mechanism.as_str(),
                            "reason" => reason
                        )
                        .increment(1);
                        Err(AppError::unauthenticated())
                    }
                    Err(Refusal::Hidden) => Err(AppError::not_found()),
                    Err(Refusal::Failure(error)) => Err(error),
                }
            }
            AuthOutcome::Rejected(reason) => {
                self.failed(mechanism, reason.as_str(), &keys).await;
                Err(AppError::unauthenticated())
            }
            AuthOutcome::NotApplicable => {
                self.failed(mechanism, RejectReason::Malformed.as_str(), &keys).await;
                Err(AppError::unauthenticated())
            }
        }
    }
}

