/// Turns a prefix collision into a lost race: the transaction starts over with a new secret.
fn collision(error: StoreError) -> AppError {
    match error {
        StoreError::UniqueViolation(UniqueKey::CredentialPrefix) => AppError::from(StoreError::SerializationFailure),
        other => other.into(),
    }
}

/// The hash input of a secret.
fn secret(text: &str) -> SecretString {
    SecretString::from(text.to_owned())
}

/// The page of `items` (already in id order) after the cursor of `request`, and the cursor of the next page.
fn slice_page<T>(
    core: &AppCore,
    ctx: &RequestContext,
    listing: &str,
    items: Vec<T>,
    id_of: impl Fn(&T) -> Uuid,
    page: &PageRequest,
) -> AppResult<Page<T>> {
    let request: PageReq = paging::page_request(core, ctx, listing, page)?;
    let limit = usize::try_from(request.effective_limit()).unwrap_or(usize::MAX);
    let mut rest = items
        .into_iter()
        .filter(|item| request.after.is_none_or(|after| id_of(item) > after));
    let mut taken: Vec<T> = rest.by_ref().take(limit).collect();
    let next = if rest.next().is_some() {
        paging::next_cursor(core, ctx, listing, taken.last().map(&id_of))?
    } else {
        None
    };
    taken.shrink_to_fit();
    Ok(Page::new(taken, next))
}

fn app_password_view(password: &AppPassword) -> AppPasswordView {
    AppPasswordView {
        id: password.id,
        label: password.label.clone(),
        prefix: password.prefix.clone(),
        last_used_at: password.last_used_at,
        revoked_at: password.revoked_at,
        created_at: password.created_at,
    }
}

fn feed_token_view(token: &FeedToken) -> FeedTokenView {
    FeedTokenView {
        id: token.id,
        mode: token.mode,
        calendar_ids: token.calendar_ids.clone(),
        prefix: token.prefix.clone(),
        revoked_at: token.revoked_at,
        created_at: token.created_at,
    }
}

pub(crate) fn api_token_view(token: &ApiToken, principal: Option<PrincipalName>) -> ApiTokenView {
    ApiTokenView {
        id: token.id,
        kind: token.kind,
        principal_id: token.principal_id,
        principal,
        label: token.label.clone(),
        scopes: token.scopes,
        prefix: token.prefix.clone(),
        expires_at: token.expires_at,
        allowed_origins: token.allowed_origins.clone(),
        created_by: token.created_by,
        last_used_at: token.last_used_at,
        revoked_at: token.revoked_at,
        created_at: token.created_at,
    }
}

/// Normalizes the origins an API token may be used from: scheme, host and port only.
fn check_origins(origins: &[String]) -> AppResult<Vec<String>> {
    if origins.len() > MAX_ORIGINS {
        return Err(field_error(
            "/allowed_origins",
            "too-many",
            "A token can be bound to at most 20 origins.",
        ));
    }
    let mut checked: Vec<String> = Vec::with_capacity(origins.len());
    for origin in origins {
        let valid = Url::parse(origin).ok().filter(|url| {
            matches!(url.scheme(), "http" | "https")
                && url.host_str().is_some()
                && url.path() == "/"
                && url.query().is_none()
                && url.fragment().is_none()
                && url.username().is_empty()
        });
        let Some(url) = valid else {
            return Err(field_error(
                "/allowed_origins",
                "invalid-origin",
                "An origin is a scheme, a host and an optional port, for example https://app.example.org.",
            ));
        };
        let normalized = url.origin().ascii_serialization();
        if !checked.contains(&normalized) {
            checked.push(normalized);
        }
    }
    Ok(checked)
}

/// What a feed token mint creates: a new token, or the replacement of one.
#[derive(Debug, Clone, Copy)]
enum Mint<'a> {
    /// A new token of `mode` for `calendars`.
    New {
        mode: FeedMode,
        calendars: &'a [CalendarId],
    },
    /// A token that replaces this one and keeps its mode and calendars; the old one is revoked.
    Rotate(TokenId),
}

/// The error of a tenant that turned subscription feeds off.
fn feeds_disabled() -> AppError {
    AppError::feature_not_enabled().with_public_message(SafeMessage::from_static(
        "Subscription feeds are not enabled for this tenant.",
    ))
}

/// Whether the scope is one of the MCP scopes.
const fn is_mcp_scope(scope: Scope) -> bool {
    matches!(scope, Scope::McpRead | Scope::McpWrite | Scope::McpScheduleExternal)
}

/// Whether the caller may hand out `scopes` by the rule that a token mints tokens with a subset of its own scopes. The
/// server itself (the internal channel: `davhaven admin`) is trusted.
fn within_own_scopes(ctx: &RequestContext, scopes: ScopeSet) -> bool {
    ctx.channel == Channel::Internal || scopes.is_subset_of(ctx.scopes)
}

/// `scopes` without the MCP scopes: what every token has to take from its minter, whatever the principal is.
fn without_mcp(scopes: ScopeSet) -> ScopeSet {
    scopes.iter().filter(|scope| !is_mcp_scope(*scope)).collect()
}

/// The scope of the management API that reaches what `scope` reaches over MCP: reading events for `mcp:read`, writing
/// them for `mcp:write` and for `mcp:schedule_external` (the API sends invitations by mail when a write asks for it,
/// `notify_attendees`). Every other scope is its own equivalent.
///
/// A token that mints an MCP scope for a service principal without holding the scope itself (a tenant token cannot)
/// has to hold this one: handing out MCP access must never be more than the minter could do through the API. The
/// rule matters most for `mcp:write`, because MCP does not cap managed calendars at read as DAV does, so the token
/// reaches what `events:write` reaches there.
const fn api_equivalent(scope: Scope) -> Scope {
    match scope {
        Scope::McpRead => Scope::EventsRead,
        Scope::McpWrite | Scope::McpScheduleExternal => Scope::EventsWrite,
        other => other,
    }
}

/// The delegation rule for the MCP scopes of a principal token for `principal`.
///
/// The other scopes of the token were checked before the transaction began (`within_own_scopes` of [`without_mcp`]).
/// A minter that holds an MCP scope itself hands it out like every other scope. One that does not (a tenant token never
/// does) may hand them to a **service principal** if it holds the API scope that reaches the same
/// ([`api_equivalent`]); for every other kind of principal the plain subset rule stays, so MCP scopes reach a user only
/// from the operator (the internal channel is trusted).
///
/// # Errors
///
/// `Forbidden`, with a message that says which of the two rules was not met.
fn check_mcp_delegation(ctx: &RequestContext, scopes: ScopeSet, principal: &Principal) -> AppResult<()> {
    let mcp: ScopeSet = scopes.iter().filter(|scope| is_mcp_scope(*scope)).collect();
    if mcp.is_empty() || within_own_scopes(ctx, mcp) {
        return Ok(());
    }
    let message = if principal.kind == PrincipalKind::Service {
        if within_own_scopes(ctx, mcp.iter().map(api_equivalent).collect()) {
            return Ok(());
        }
        "A token can grant MCP scopes to a service principal only together with the API scopes that reach the same \
         data: events:read for mcp:read, events:write for mcp:write and mcp:schedule_external."
    } else {
        // A tenant token cannot hold MCP scopes at all, so the plain rule would read as a dead end to whoever asks
        // only for them: say where they go.
        "A token cannot grant scopes it does not have itself. MCP scopes can be granted through the API to a service \
         principal only."
    };
    Err(AppError::forbidden().with_public_message(SafeMessage::from_static(message)))
}

/// The refusal of scopes the caller may not hand out.
fn not_within_own_scopes() -> AppError {
    AppError::forbidden().with_public_message(SafeMessage::from_static(
        "A token cannot grant scopes it does not have itself.",
    ))
}

/// The error of a tenant that has not switched MCP on (`tenant.settings.mcp_enabled`, off by default).
fn mcp_disabled() -> AppError {
    AppError::feature_not_enabled().with_public_message(SafeMessage::from_static("MCP is not enabled for this tenant."))
}

impl CredentialServiceImpl {
    /// A fresh app password.
    fn fresh_app_password(&self) -> AppResult<AppPasswordText> {
        AppPasswordText::from_random(
            &self
                .core
                .deps()
                .ids
                .random_bytes(davhaven_domain::credential_format::APP_PASSWORD_RANDOM_BYTES),
        )
        .ok_or_else(|| AppError::internal(StoreError::internal("not enough random bytes")))
    }

    /// A fresh token of `kind`.
    fn fresh_token(&self, kind: CredentialKind) -> AppResult<TokenText> {
        let ids = &self.core.deps().ids;
        TokenText::from_random(
            kind,
            &ids.random_bytes(davhaven_domain::credential_format::TOKEN_PREFIX_RANDOM_BYTES),
            &ids.random_bytes(davhaven_domain::credential_format::TOKEN_SECRET_RANDOM_BYTES),
        )
        .ok_or_else(|| AppError::internal(StoreError::internal("not enough random bytes")))
    }

    /// Stores the hash of an app password of `owner` and audits its creation, in the transaction.
    async fn insert_app_password(
        &self,
        journal: &Journal<'_>,
        tx: &mut dyn Tx,
        ctx: &RequestContext,
        owner: &Principal,
        label: &str,
        password: &AppPasswordText,
    ) -> AppResult<AppPassword> {
        let deps = self.core.deps();
        if owner.kind == PrincipalKind::Group {
            return Err(invalid("A group cannot log in and has no app passwords."));
        }
        let hashed = deps
            .hasher
            .hash(CredentialKind::AppPassword, &secret(password.expose()));
        let now = deps.clock.now();
        let row = AppPassword {
            id: CredentialId::from_uuid(deps.ids.new_id()),
            tenant_id: ctx.tenant,
            principal_id: owner.id,
            label: label.to_owned(),
            prefix: password.prefix().to_owned(),
            hash: hashed.hash,
            pepper_kid: hashed.pepper_kid,
            last_used_at: None,
            revoked_at: None,
            created_at: now,
            updated_at: now,
            version: 1,
        };
        let stored = tx.credentials().create_app_password(row).await.map_err(collision)?;
        journal
            .audit(
                tx,
                AuditEvent::CredentialCreated(CredentialAudit {
                    kind: CredentialKind::AppPassword,
                    credential: stored.id.as_uuid(),
                    principal: Some(owner.id),
                }),
            )
            .await?;
        Ok(stored)
    }

    /// Stores the hash of a feed token and audits its creation, in the transaction.
    async fn insert_feed_token(
        &self,
        journal: &Journal<'_>,
        tx: &mut dyn Tx,
        ctx: &RequestContext,
        owner: &Principal,
        (mode, calendars): (FeedMode, Vec<CalendarId>),
        token: &TokenText,
    ) -> AppResult<FeedToken> {
        let deps = self.core.deps();
        let hashed = deps.hasher.hash(CredentialKind::FeedToken, &secret(token.secret()));
        let now = deps.clock.now();
        let row = FeedToken {
            id: TokenId::from_uuid(deps.ids.new_id()),
            tenant_id: ctx.tenant,
            principal_id: owner.id,
            mode,
            calendar_ids: calendars,
            prefix: token.prefix().to_owned(),
            hash: hashed.hash,
            pepper_kid: hashed.pepper_kid,
            revoked_at: None,
            created_at: now,
            updated_at: now,
            version: 1,
        };
        let stored = tx.credentials().create_feed_token(row).await.map_err(collision)?;
        journal
            .audit(
                tx,
                AuditEvent::CredentialCreated(CredentialAudit {
                    kind: CredentialKind::FeedToken,
                    credential: stored.id.as_uuid(),
                    principal: Some(owner.id),
                }),
            )
            .await?;
        Ok(stored)
    }

    /// Mints an app password for `principal` and stores its hash (one transaction; a prefix collision starts over).
    async fn mint_app_password(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        label: &str,
    ) -> AppResult<(AppPasswordCreated, Principal)> {
        let journal = Journal::new(&self.core, ctx);
        retrying(false, || async {
            let password = self.fresh_app_password()?;
            let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            let owner = principal_named(tx.as_mut(), principal).await?;
            let stored = self
                .insert_app_password(&journal, tx.as_mut(), ctx, &owner, label, &password)
                .await?;
            tx.commit().await?;
            Ok((
                AppPasswordCreated {
                    id: stored.id,
                    label: stored.label,
                    prefix: stored.prefix,
                    password: password.expose().to_owned(),
                    created_at: stored.created_at,
                },
                owner,
            ))
        })
        .await
    }

    /// Mints a feed token for `principal`.
    async fn mint_feed_token(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        mint: Mint<'_>,
    ) -> AppResult<FeedTokenCreated> {
        let deps = self.core.deps();
        let journal = Journal::new(&self.core, ctx);
        retrying(false, || async {
            let token = self.fresh_token(CredentialKind::FeedToken)?;
            let mut tx = deps.database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            let tenant = tx.tenant().get().await?;
            if !tenant.settings.feeds_enabled {
                return Err(feeds_disabled());
            }
            let owner = principal_named(tx.as_mut(), principal).await?;
            let plan = match mint {
                Mint::New { mode, calendars } => {
                    self.check_feed_calendars(tx.as_mut(), owner.id, calendars).await?;
                    (mode, calendars.to_vec())
                }
                Mint::Rotate(old) => {
                    let old = tx.credentials().get_feed_token(old).await?;
                    if old.principal_id != owner.id || old.revoked_at.is_some() {
                        return Err(AppError::not_found());
                    }
                    tx.credentials().revoke_feed_token(old.id).await?;
                    journal
                        .audit(
                            tx.as_mut(),
                            AuditEvent::CredentialRevoked(CredentialAudit {
                                kind: CredentialKind::FeedToken,
                                credential: old.id.as_uuid(),
                                principal: Some(owner.id),
                            }),
                        )
                        .await?;
                    (old.mode, old.calendar_ids.clone())
                }
            };
            let stored = self
                .insert_feed_token(&journal, tx.as_mut(), ctx, &owner, plan, &token)
                .await?;
            tx.commit().await?;
            Ok(FeedTokenCreated {
                token: feed_token_view(&stored),
                feed_url: deps.urls.for_tenant(&tenant.settings).feed_url(token.expose().as_str()),
            })
        })
        .await
    }

    /// Checks that the principal may read every calendar a feed is made of, with one load of the facts.
    async fn check_feed_calendars(
        &self,
        tx: &mut dyn Tx,
        principal: PrincipalId,
        calendars: &[CalendarId],
    ) -> AppResult<()> {
        if calendars.is_empty() || calendars.len() > MAX_FEED_CALENDARS {
            return Err(field_error(
                "/calendar_ids",
                "invalid-count",
                "A feed contains between one and fifty calendars.",
            ));
        }
        let subject = davhaven_domain::Subject::new(
            Actor::FeedReader {
                principal,
                token: TokenId::from_uuid(Uuid::nil()),
            },
            ScopeSet::empty(),
        );
        let facts: HashMap<CalendarId, davhaven_domain::AccessFacts> = tx
            .calendars()
            .access_facts_many(calendars, Some(principal))
            .await?
            .into_iter()
            .collect();
        for calendar in calendars {
            let allowed = facts
                .get(calendar)
                .is_some_and(|facts| decide(&subject, Channel::Feed, facts, Operation::ReadFeed) == Decision::Allow);
            if !allowed {
                return Err(field_error(
                    "/calendar_ids",
                    "not-readable",
                    "The principal cannot read one of the calendars.",
                ));
            }
        }
        Ok(())
    }

    /// Validates the request for an API token and fills in what the kind needs.
    fn check_api_token(&self, ctx: &RequestContext, request: &ApiTokenCreate) -> AppResult<(String, Vec<String>)> {
        let deps = self.core.deps();
        let label = clean_name("/label", &request.label, MAX_LABEL)?;
        if request.kind == TokenKind::System {
            return Err(field_error(
                "/kind",
                "not-allowed",
                "System tokens are created by the operator, not through the API.",
            ));
        }
        if request.scopes.is_empty() {
            return Err(field_error("/scopes", "empty", "A token needs at least one scope."));
        }
        if request.scopes.first_not_allowed_for(request.kind).is_some() {
            return Err(field_error(
                "/scopes",
                "not-allowed",
                "A scope is not allowed for this kind of token.",
            ));
        }
        // A token only mints tokens whose scopes are a subset of its own; server work is trusted. The MCP scopes of a
        // principal token have one exception, for service principals, which can be decided only once the principal is
        // read (`check_mcp_delegation`); for every other kind `allowed_for` has refused them, so this is the whole
        // set.
        if !within_own_scopes(ctx, without_mcp(request.scopes)) {
            return Err(not_within_own_scopes());
        }
        match (request.kind, &request.principal) {
            (TokenKind::Principal, None) => {
                return Err(field_error(
                    "/principal",
                    "required",
                    "A principal token needs a principal.",
                ));
            }
            (TokenKind::Tenant, Some(_)) => {
                return Err(field_error(
                    "/principal",
                    "not-allowed",
                    "A tenant token acts for no principal.",
                ));
            }
            _ => {}
        }
        let now = deps.clock.now();
        let needs_expiry = request.scopes.iter().any(Scope::requires_expiry);
        match request.expires_at {
            None if needs_expiry => {
                return Err(field_error(
                    "/expires_at",
                    "required",
                    "Tokens with MCP scopes need an expiry.",
                ));
            }
            Some(at) if at <= now => {
                return Err(field_error(
                    "/expires_at",
                    "in-the-past",
                    "The expiry must be in the future.",
                ));
            }
            Some(at) if needs_expiry => {
                let longest = now + ChronoDuration::days(i64::from(deps.config.max_mcp_token_days));
                if at > longest {
                    return Err(field_error(
                        "/expires_at",
                        "too-far",
                        "The expiry is beyond the longest lifetime of a token with MCP scopes.",
                    ));
                }
            }
            _ => {}
        }
        Ok((label, check_origins(&request.allowed_origins)?))
    }
}

#[async_trait]
impl CredentialService for CredentialServiceImpl {
    async fn list_app_passwords(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        page: PageRequest,
    ) -> AppResult<Page<AppPasswordView>> {
        admin(ctx, AdminOperation::ListAppPasswords)?;
        let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadOnly).await?;
        let owner = principal_named(tx.as_mut(), principal).await?;
        let passwords = tx.credentials().list_app_passwords(owner.id).await?;
        tx.commit().await?;
        let listing = format!("app-passwords/{}", owner.id);
        let page = slice_page(
            &self.core,
            ctx,
            &listing,
            passwords,
            |password| password.id.as_uuid(),
            &page,
        )?;
        Ok(page.map(|password| app_password_view(&password)))
    }

    async fn create_app_password(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        request: AppPasswordCreate,
    ) -> AppResult<AppPasswordCreated> {
        admin(ctx, AdminOperation::CreateAppPassword)?;
        let label = clean_name("/label", &request.label, MAX_LABEL)?;
        Ok(self.mint_app_password(ctx, principal, &label).await?.0)
    }

    async fn revoke_app_password(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        id: CredentialId,
    ) -> AppResult<()> {
        admin(ctx, AdminOperation::RevokeAppPassword)?;
        let journal = Journal::new(&self.core, ctx);
        retrying(false, || async {
            let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            let owner = principal_named(tx.as_mut(), principal).await?;
            let password = tx.credentials().get_app_password(id).await?;
            if password.principal_id != owner.id {
                return Err(AppError::not_found());
            }
            if password.revoked_at.is_none() {
                tx.credentials().revoke_app_password(id).await?;
                tx.principals().bump_credential_generation(owner.id).await?;
                journal
                    .audit(
                        tx.as_mut(),
                        AuditEvent::CredentialRevoked(CredentialAudit {
                            kind: CredentialKind::AppPassword,
                            credential: id.as_uuid(),
                            principal: Some(owner.id),
                        }),
                    )
                    .await?;
            }
            tx.commit().await?;
            Ok(())
        })
        .await
    }

    async fn list_api_tokens(&self, ctx: &RequestContext, page: PageRequest) -> AppResult<Page<ApiTokenView>> {
        admin(ctx, AdminOperation::ListApiTokens)?;
        let request: PageReq = paging::page_request(&self.core, ctx, "api-tokens", &page)?;
        let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadOnly).await?;
        let rows = tx
            .credentials()
            .list_api_tokens(
                &ApiTokenFilter {
                    principal: None,
                    kind: None,
                    include_revoked: true,
                },
                request,
            )
            .await?;
        let next = paging::next_cursor(&self.core, ctx, "api-tokens", rows.next)?;
        let mut names: HashMap<PrincipalId, PrincipalName> = HashMap::new();
        let mut items = Vec::with_capacity(rows.items.len());
        for token in &rows.items {
            let name = match token.principal_id {
                Some(id) => {
                    if let Some(known) = names.get(&id) {
                        Some(known.clone())
                    } else {
                        let principal = tx.principals().get(id).await?;
                        names.insert(id, principal.name.clone());
                        Some(principal.name)
                    }
                }
                None => None,
            };
            items.push(api_token_view(token, name));
        }
        tx.commit().await?;
        Ok(Page::new(items, next))
    }

    async fn create_api_token(&self, ctx: &RequestContext, request: ApiTokenCreate) -> AppResult<ApiTokenCreated> {
        admin(ctx, AdminOperation::CreateApiToken)?;
        let (label, origins) = self.check_api_token(ctx, &request)?;
        let deps = self.core.deps();
        let journal = Journal::new(&self.core, ctx);
        retrying(false, || async {
            let token = TokenText::from_random(
                CredentialKind::ApiToken,
                &deps
                    .ids
                    .random_bytes(davhaven_domain::credential_format::TOKEN_PREFIX_RANDOM_BYTES),
                &deps
                    .ids
                    .random_bytes(davhaven_domain::credential_format::TOKEN_SECRET_RANDOM_BYTES),
            )
            .ok_or_else(|| AppError::internal(StoreError::internal("not enough random bytes")))?;
            let hashed = deps.hasher.hash(CredentialKind::ApiToken, &secret(token.secret()));
            let mut tx = deps.database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            // MCP is opt-in per tenant (`tenant.settings.mcp_enabled`): no token that could use it is minted for a
            // tenant that has not switched it on, as no feed token is minted for a tenant without feeds.
            if request.scopes.iter().any(is_mcp_scope) && !tx.tenant().get().await?.settings.mcp_enabled {
                return Err(mcp_disabled());
            }
            // A token never outlives the token that minted it: a token with an expiry cannot mint a way around it.
            let minter_expiry = match ctx.actor.token() {
                Some(minter) => {
                    found(tx.credentials().get_api_token(minter).await)?.and_then(|minter| minter.expires_at)
                }
                None => None,
            };
            let expires_at = match (request.expires_at, minter_expiry) {
                (Some(requested), Some(limit)) => Some(requested.min(limit)),
                (None, Some(limit)) => Some(limit),
                (requested, None) => requested,
            };
            let principal = match &request.principal {
                Some(name) => Some(principal_named(tx.as_mut(), name).await?),
                None => None,
            };
            if principal
                .as_ref()
                .is_some_and(|principal| principal.kind == PrincipalKind::Group)
            {
                return Err(field_error(
                    "/principal",
                    "not-allowed",
                    "A group cannot act through a token.",
                ));
            }
            if let Some(principal) = &principal {
                check_mcp_delegation(ctx, request.scopes, principal)?;
            }
            let now = deps.clock.now();
            let row = ApiToken {
                id: TokenId::from_uuid(deps.ids.new_id()),
                tenant_id: Some(ctx.tenant),
                kind: request.kind,
                principal_id: principal.as_ref().map(|principal| principal.id),
                label: label.clone(),
                scopes: request.scopes,
                prefix: token.prefix().to_owned(),
                hash: hashed.hash,
                pepper_kid: hashed.pepper_kid,
                expires_at,
                created_by: ctx.actor.token(),
                allowed_origins: origins.clone(),
                last_used_at: None,
                revoked_at: None,
                created_at: now,
                updated_at: now,
                version: 1,
            };
            let stored = tx.credentials().create_api_token(row).await.map_err(collision)?;
            journal
                .audit(
                    tx.as_mut(),
                    AuditEvent::TokenCreated(TokenAudit {
                        token: stored.id,
                        kind: stored.kind,
                        principal: stored.principal_id,
                        scopes: stored.scopes,
                        expires_at: stored.expires_at,
                    }),
                )
                .await?;
            tx.commit().await?;
            Ok(ApiTokenCreated {
                token: api_token_view(&stored, principal.map(|principal| principal.name)),
                secret: token.expose().as_str().to_owned(),
            })
        })
        .await
    }

    async fn revoke_api_token(&self, ctx: &RequestContext, id: TokenId) -> AppResult<()> {
        admin(ctx, AdminOperation::RevokeApiToken)?;
        let journal = Journal::new(&self.core, ctx);
        retrying(false, || async {
            let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            let token = tx.credentials().get_api_token(id).await?;
            if token.revoked_at.is_none() {
                tx.credentials().revoke_api_token(id).await?;
                if let Some(principal) = token.principal_id {
                    tx.principals().bump_credential_generation(principal).await?;
                }
                journal
                    .audit(
                        tx.as_mut(),
                        AuditEvent::TokenRevoked(TokenRevocationAudit { token: id }),
                    )
                    .await?;
            }
            tx.commit().await?;
            Ok(())
        })
        .await
    }

    async fn list_feed_tokens(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        page: PageRequest,
    ) -> AppResult<Page<FeedTokenView>> {
        admin(ctx, AdminOperation::ListFeedTokens)?;
        let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadOnly).await?;
        let owner = principal_named(tx.as_mut(), principal).await?;
        let tokens = tx.credentials().list_feed_tokens(owner.id).await?;
        tx.commit().await?;
        let listing = format!("feed-tokens/{}", owner.id);
        let page = slice_page(&self.core, ctx, &listing, tokens, |token| token.id.as_uuid(), &page)?;
        Ok(page.map(|token| feed_token_view(&token)))
    }

    async fn create_feed_token(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        request: FeedTokenCreate,
    ) -> AppResult<FeedTokenCreated> {
        admin(ctx, AdminOperation::CreateFeedToken)?;
        self.mint_feed_token(
            ctx,
            principal,
            Mint::New {
                mode: request.mode,
                calendars: &request.calendar_ids,
            },
        )
        .await
    }

    async fn revoke_feed_token(&self, ctx: &RequestContext, principal: &PrincipalName, id: TokenId) -> AppResult<()> {
        admin(ctx, AdminOperation::RevokeFeedToken)?;
        let journal = Journal::new(&self.core, ctx);
        retrying(false, || async {
            let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            let owner = principal_named(tx.as_mut(), principal).await?;
            let token = tx.credentials().get_feed_token(id).await?;
            if token.principal_id != owner.id {
                return Err(AppError::not_found());
            }
            if token.revoked_at.is_none() {
                tx.credentials().revoke_feed_token(id).await?;
                journal
                    .audit(
                        tx.as_mut(),
                        AuditEvent::CredentialRevoked(CredentialAudit {
                            kind: CredentialKind::FeedToken,
                            credential: id.as_uuid(),
                            principal: Some(owner.id),
                        }),
                    )
                    .await?;
            }
            tx.commit().await?;
            Ok(())
        })
        .await
    }

    async fn rotate_feed_token(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        id: TokenId,
    ) -> AppResult<FeedTokenCreated> {
        admin(ctx, AdminOperation::RotateFeedToken)?;
        self.mint_feed_token(ctx, principal, Mint::Rotate(id)).await
    }

    async fn client_config(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        kind: ClientConfigKind,
    ) -> AppResult<ClientConfigResponse> {
        match kind {
            ClientConfigKind::Generic => {
                admin(ctx, AdminOperation::GetClientConfig)?;
                self.generic_config(ctx, principal)
                    .await
                    .map(|generic| ClientConfigResponse::Generic(Box::new(generic)))
            }
            ClientConfigKind::AppleMobileconfig(request) => {
                admin(ctx, AdminOperation::CreateClientConfig)?;
                self.apple_profile(ctx, principal, &request.app_password_label, request.include_feed)
                    .await
            }
            ClientConfigKind::Davx5(request) => {
                admin(ctx, AdminOperation::CreateClientConfig)?;
                self.davx5_login(ctx, principal, &request.app_password_label).await
            }
        }
    }
}

impl CredentialServiceImpl {
    /// The login name a person types: `name@login_domain` with a login domain, the bare name otherwise.
    fn login_of(tenant: &davhaven_domain::Tenant, principal: &Principal) -> String {
        match &tenant.login_domain {
            Some(domain) => format!("{}@{domain}", principal.name),
            None => principal.name.to_string(),
        }
    }

    async fn generic_config(&self, ctx: &RequestContext, principal: &PrincipalName) -> AppResult<ClientConfigGeneric> {
        let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadOnly).await?;
        let tenant = tx.tenant().get().await?;
        let owner = principal_named(tx.as_mut(), principal).await?;
        tx.commit().await?;
        let urls = self.core.deps().urls.for_tenant(&tenant.settings);
        let path = |make: fn(davhaven_domain::TenantSlug, PrincipalName) -> ResourcePath| {
            urls.dav_url(&make(tenant.slug.clone(), owner.name.clone()))
        };
        Ok(ClientConfigGeneric {
            tenant: tenant.slug.clone(),
            username: Self::login_of(&tenant, &owner),
            login_domain: tenant.login_domain.clone(),
            well_known_url: urls.well_known_caldav(),
            server_url: urls.dav_root(),
            principal_url: path(|tenant, principal| ResourcePath::Principal { tenant, principal }),
            calendar_home_url: path(|tenant, principal| ResourcePath::Home { tenant, principal }),
        })
    }

    /// Mints what an Apple profile contains, an app password and, when asked, a feed token for the personal calendar, and the
    /// profile document that carries them (signed when the deployment has a certificate): **all in one transaction**, after
    /// everything that can refuse has been checked. The document is built and signed before the commit, so that a request that
    /// fails at any step (a signer that cannot sign, a worker that does not finish in time) stores no credential whose secret
    /// nobody was shown.
    async fn mint_profile(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        label: &str,
        include_feed: bool,
    ) -> AppResult<MobileConfig> {
        let deps = self.core.deps();
        let journal = Journal::new(&self.core, ctx);
        retrying(false, || async {
            let password = self.fresh_app_password()?;
            let token = if include_feed {
                Some(self.fresh_token(CredentialKind::FeedToken)?)
            } else {
                None
            };
            let mut tx = deps.database.begin(ctx.tenant, TxMode::ReadWrite).await?;
            let tenant = tx.tenant().get().await?;
            let owner = principal_named(tx.as_mut(), principal).await?;
            // Everything that can refuse comes first.
            let calendar = if include_feed {
                if !tenant.settings.feeds_enabled {
                    return Err(feeds_disabled());
                }
                let candidates = tx.calendars().list_owned(owner.id).await?;
                // The personal calendar, or the first calendar the principal owns when the tenant has none.
                let Some(calendar) = candidates
                    .iter()
                    .find(|calendar| calendar.kind == CalendarKind::Personal)
                    .or_else(|| candidates.first())
                else {
                    return Err(field_error(
                        "/include_feed",
                        "no-calendar",
                        "The principal has no calendar to subscribe to.",
                    ));
                };
                self.check_feed_calendars(tx.as_mut(), owner.id, &[calendar.id]).await?;
                Some(calendar.id)
            } else {
                None
            };
            self.insert_app_password(&journal, tx.as_mut(), ctx, &owner, label, &password)
                .await?;
            let feed = match (&token, calendar) {
                (Some(token), Some(calendar)) => {
                    self.insert_feed_token(
                        &journal,
                        tx.as_mut(),
                        ctx,
                        &owner,
                        (FeedMode::Full, vec![calendar]),
                        token,
                    )
                    .await?;
                    Some(deps.urls.for_tenant(&tenant.settings).feed_url(token.expose().as_str()))
                }
                _ => None,
            };
            // The document is made while the transaction is open: if it cannot be made, nothing is stored.
            let body = self
                .profile_document(&tenant, &owner, password.expose(), feed.as_ref())
                .await?;
            tx.commit().await?;
            Ok(MobileConfig {
                filename: format!("{}.mobileconfig", tenant.slug),
                body,
            })
        })
        .await
    }

    /// The Apple configuration profile of a principal (see [`mint_profile`](Self::mint_profile) for what it mints).
    async fn apple_profile(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        label: &str,
        include_feed: bool,
    ) -> AppResult<ClientConfigResponse> {
        let label = clean_name("/app_password_label", label, MAX_LABEL)?;
        let profile = self.mint_profile(ctx, principal, &label, include_feed).await?;
        Ok(ClientConfigResponse::Mobileconfig(profile))
    }

    /// The profile document of `owner` in `tenant` with the new app `password` and the feed URL, if there is one, signed with
    /// the certificate of the deployment when it has one.
    async fn profile_document(
        &self,
        tenant: &davhaven_domain::Tenant,
        owner: &Principal,
        password: &str,
        feed: Option<&Url>,
    ) -> AppResult<Vec<u8>> {
        let urls = self.core.deps().urls.for_tenant(&tenant.settings);
        let server = urls.dav_base().clone();
        let prefix = tenant
            .settings
            .client_config
            .apple_identifier_prefix
            .clone()
            .unwrap_or_else(|| profile::default_prefix(&server));
        let organization = tenant
            .settings
            .client_config
            .organization_name
            .clone()
            .unwrap_or_else(|| tenant.display_name.clone());
        let principal_path = ResourcePath::Principal {
            tenant: tenant.slug.clone(),
            principal: owner.name.clone(),
        }
        .format();
        let username = Self::login_of(tenant, owner);
        let body = profile::mobileconfig(&profile::Profile {
            identifier_prefix: &prefix,
            organization: &organization,
            principal: owner.id,
            account_name: &tenant.display_name,
            server: &server,
            principal_path: &principal_path,
            username: &username,
            password,
            feed,
        })
        .into_bytes();
        self.signed(body).await
    }

    /// The profile as it is handed out: signed with the certificate of the deployment when it has one, else as it is.
    ///
    /// The document carries the minted app password, so the copy that goes to the blocking thread is wiped there, and the
    /// signer sees nothing but the bytes: no tenant, no principal. The wait is bounded like every blocking job
    /// (`ENGINEERING_RULES` R14).
    async fn signed(&self, profile: Vec<u8>) -> AppResult<Vec<u8>> {
        let deps = self.core.deps();
        let Some(signer) = deps.profile_signer.clone() else {
            return Ok(profile);
        };
        let now = deps.clock.now();
        let job = tokio::task::spawn_blocking(move || {
            let mut profile = profile;
            let document = signer.sign(&profile, now);
            profile.zeroize();
            document
        });
        match tokio::time::timeout(Deadline::budget(&self.core), job).await {
            Ok(Ok(document)) => Ok(document?),
            Ok(Err(_)) | Err(_) => Err(AppError::unavailable()),
        }
    }

    async fn davx5_login(
        &self,
        ctx: &RequestContext,
        principal: &PrincipalName,
        label: &str,
    ) -> AppResult<ClientConfigResponse> {
        let label = clean_name("/app_password_label", label, MAX_LABEL)?;
        let (created, owner) = self.mint_app_password(ctx, principal, &label).await?;
        let tenant = {
            let mut tx = self.core.deps().database.begin(ctx.tenant, TxMode::ReadOnly).await?;
            let tenant = tx.tenant().get().await?;
            tx.commit().await?;
            tenant
        };
        let urls = self.core.deps().urls.for_tenant(&tenant.settings);
        let login_uri = profile::davx5_uri(urls.dav_base(), &Self::login_of(&tenant, &owner), &created.password)
            .ok_or_else(|| AppError::internal(StoreError::internal("the server URL cannot carry credentials")))?;
        Ok(ClientConfigResponse::Davx5(ClientConfigDavx5 {
            app_password_id: created.id,
            login_uri,
        }))
    }
}

#[cfg(test)]
mod tests {
    use chrono::TimeZone as _;
    use davhaven_domain::ErrorKind;

    use super::*;

    fn token(n: u128) -> TokenId {
        TokenId::from_uuid(Uuid::from_u128(n))
    }

    fn at(seconds: i64) -> DateTime<Utc> {
        Utc.with_ymd_and_hms(2027, 3, 1, 9, 0, 0).unwrap() + ChronoDuration::seconds(seconds)
    }

    const OPENED: TripsDue = TripsDue {
        closed: None,
        opened: true,
    };

    #[tokio::test]
    async fn a_flood_of_refusals_becomes_one_record_per_minute_and_a_total() {
        let log = TripLog::default();
        assert_eq!(log.note(token(1), BudgetClass::McpRead, at(0)).await, OPENED);
        for second in [1, 30, 59] {
            assert_eq!(
                log.note(token(1), BudgetClass::McpRead, at(second)).await,
                TripsDue::default(),
                "inside the window nothing is recorded"
            );
        }
        assert_eq!(
            log.note(token(1), BudgetClass::McpRead, at(60)).await,
            TripsDue {
                closed: Some(4),
                opened: true
            },
            "the next refusal after the window closes it with its total and opens the next"
        );
        assert_eq!(
            log.note(token(1), BudgetClass::McpRead, at(200)).await,
            OPENED,
            "a window with a single refusal has no total to record"
        );
    }

    #[tokio::test]
    async fn every_token_and_budget_has_its_own_window() {
        let log = TripLog::default();
        assert_eq!(log.note(token(1), BudgetClass::McpRead, at(0)).await, OPENED);
        assert_eq!(log.note(token(1), BudgetClass::McpWrite, at(1)).await, OPENED);
        assert_eq!(log.note(token(2), BudgetClass::McpRead, at(2)).await, OPENED);
        assert_eq!(
            log.note(token(1), BudgetClass::McpRead, at(3)).await,
            TripsDue::default()
        );
    }

    #[tokio::test]
    async fn the_table_of_windows_is_bounded_and_drops_ended_windows_first() {
        let log = TripLog::default();
        let full = u128::try_from(MAX_TRIP_WINDOWS).unwrap();
        for n in 0..full {
            log.note(token(n), BudgetClass::McpRead, at(0)).await;
        }
        // A newcomer half a minute later finds every window still open: the table is cleared, so nothing is kept
        // beyond the bound, and an open window starts again.
        assert_eq!(log.note(token(full), BudgetClass::McpRead, at(30)).await, OPENED);
        assert_eq!(log.windows.lock().await.len(), 1);
        assert_eq!(
            log.note(token(0), BudgetClass::McpRead, at(31)).await,
            OPENED,
            "a cleared window is recorded again"
        );
        // With the table full of windows that ended, only those are dropped.
        let log = TripLog::default();
        for n in 0..full - 1 {
            log.note(token(n), BudgetClass::McpRead, at(0)).await;
        }
        log.note(token(full), BudgetClass::McpWrite, at(100)).await;
        assert_eq!(log.windows.lock().await.len(), MAX_TRIP_WINDOWS);
        assert_eq!(log.note(token(full + 1), BudgetClass::McpRead, at(120)).await, OPENED);
        let windows = log.windows.lock().await;
        assert_eq!(windows.len(), 2, "the open window survives, the ended ones are gone");
        assert!(windows.contains_key(&(token(full), BudgetClass::McpWrite)));
    }

    #[tokio::test]
    async fn only_a_prefix_collision_starts_the_transaction_over() {
        // Two secrets that share a prefix are a lost race: the transaction is repeated with a new secret. Any other
        // unique key is a conflict of the request and is answered at once.
        let attempts = |key: UniqueKey| async move {
            let calls = std::sync::atomic::AtomicU32::new(0);
            let result: AppResult<()> = retrying(false, || async {
                calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                Err(collision(StoreError::UniqueViolation(key)))
            })
            .await;
            (result.unwrap_err().kind(), calls.into_inner())
        };
        assert_eq!(attempts(UniqueKey::CredentialPrefix).await, (ErrorKind::Unavailable, 3));
        assert_eq!(attempts(UniqueKey::PrincipalName).await, (ErrorKind::Conflict, 1));
    }
}
